        and "asset_face"."isVisible" = $5
        and "asset_face"."isWholeAsset" = $6
      )
      and vector_norm (face_search.embedding) >= $7
      and least(
        asset_face."boundingBoxX2" - asset_face."boundingBoxX1",
        asset_face."boundingBoxY2" - asset_face."boundingBoxY1"
      ) >= $8::float8 * greatest(asset_face."imageWidth", asset_face."imageHeight")
  ) as "face"
where
