-- PersonSuggestionRepository.getShownFaces
select distinct
  on ("face"."tile") "face"."id",
  "face"."assetId",
  "face"."updatedAt",
  "face"."fileCreatedAt"
from
  (
    select
      "asset_face"."id",
      "asset_face"."assetId",
      "asset_face"."updatedAt",
      "asset"."fileCreatedAt",
      ntile($1) over (
        order by
          asset."fileCreatedAt",
          asset_face.id
      ) as "tile",
      (
        asset_face."boundingBoxX2" - asset_face."boundingBoxX1"
      )::float8 * (
        asset_face."boundingBoxY2" - asset_face."boundingBoxY1"
      ) / greatest(
        asset_face."imageWidth" * asset_face."imageHeight",
        1
      ) as "size"
    from
      "asset_face"
      inner join "asset" on "asset"."id" = "asset_face"."assetId"
    where
      "asset_face"."personGroupId" = $2
      and (
        "asset"."ownerId" = $3
        and "asset"."deletedAt" is null
        and "asset"."visibility" in ($4, $5)
        and "asset_face"."deletedAt" is null
        and "asset_face"."isVisible" = $6
        and "asset_face"."isWholeAsset" = $7
        and (
          "asset"."isPrivate" = $8
          and (
            (
              (
                not exists (
                  select
                  from
                    "tag_asset"
                    inner join "tag" on "tag"."id" = "tag_asset"."tagId"
                  where
                    "tag_asset"."assetId" = "asset"."id"
                    and "tag"."userId" = $9
                )
                and (
                  "asset"."visibility" != 'hidden'
                  or not exists (
                    select
                    from
                      "asset" as "live_photo_still"
                    where
                      "live_photo_still"."livePhotoVideoId" = "asset"."id"
                      and exists (
                        select
                        from
                          "tag_asset"
                          inner join "tag" on "tag"."id" = "tag_asset"."tagId"
                        where
                          "tag_asset"."assetId" = "live_photo_still"."id"
                          and "tag"."userId" = $10
                      )
                  )
                )
              )
              or (
                exists (
                  select
                  from
                    "tag_asset"
                    inner join "tag_closure" on "tag_closure"."id_descendant" = "tag_asset"."tagId"
                  where
                    "tag_asset"."assetId" = "asset"."id"
                    and "tag_closure"."id_ancestor" = any ($11::uuid[])
                )
                or (
                  "asset"."visibility" = 'hidden'
                  and exists (
                    select
                    from
                      "asset" as "live_photo_still"
                    where
                      "live_photo_still"."livePhotoVideoId" = "asset"."id"
                      and exists (
                        select
                        from
                          "tag_asset"
                          inner join "tag_closure" on "tag_closure"."id_descendant" = "tag_asset"."tagId"
                        where
                          "tag_asset"."assetId" = "live_photo_still"."id"
                          and "tag_closure"."id_ancestor" = any ($12::uuid[])
                      )
                  )
                )
              )
            )
            and (
              not exists (
                select
                from
                  "tag_asset"
                  inner join "tag_closure" on "tag_closure"."id_descendant" = "tag_asset"."tagId"
                where
                  "tag_asset"."assetId" = "asset"."id"
                  and "tag_closure"."id_ancestor" = any ($13::uuid[])
              )
              and (
                "asset"."visibility" != 'hidden'
                or not exists (
                  select
                  from
                    "asset" as "live_photo_still"
                  where
                    "live_photo_still"."livePhotoVideoId" = "asset"."id"
                    and exists (
                      select
                      from
                        "tag_asset"
                        inner join "tag_closure" on "tag_closure"."id_descendant" = "tag_asset"."tagId"
                      where
                        "tag_asset"."assetId" = "live_photo_still"."id"
                        and "tag_closure"."id_ancestor" = any ($14::uuid[])
                    )
                )
              )
            )
            and "asset"."isPrivate" = $15
          )
        )
      )
  ) as "face"
order by
  "face"."tile",
  "face"."size" desc,
  "face"."id"

-- PersonSuggestionRepository.getMostSimilarFaces
with
  "query" as (
    select
      avg(l2_normalize (face_search.embedding)) as "embedding"
    from
      "asset_face"
      inner join "face_search" on "face_search"."faceId" = "asset_face"."id"
    where
      "asset_face"."personGroupId" = $1
      and "asset_face"."deletedAt" is null
  )
select
  "asset_face"."id",
  "asset_face"."assetId",
  "asset_face"."updatedAt",
  "asset"."fileCreatedAt"
from
  "asset_face"
  inner join "face_search" on "face_search"."faceId" = "asset_face"."id"
  inner join "asset" on "asset"."id" = "asset_face"."assetId"
  inner join "query" on true
where
  "asset_face"."personGroupId" = $2
  and (
    "asset"."ownerId" = $3
    and "asset"."deletedAt" is null
    and "asset"."visibility" in ($4, $5)
    and "asset_face"."deletedAt" is null
    and "asset_face"."isVisible" = $6
    and "asset_face"."isWholeAsset" = $7
    and (
      "asset"."isPrivate" = $8
      and (
        (
          (
            not exists (
              select
              from
                "tag_asset"
                inner join "tag" on "tag"."id" = "tag_asset"."tagId"
              where
                "tag_asset"."assetId" = "asset"."id"
                and "tag"."userId" = $9
            )
            and (
              "asset"."visibility" != 'hidden'
              or not exists (
                select
                from
                  "asset" as "live_photo_still"
                where
                  "live_photo_still"."livePhotoVideoId" = "asset"."id"
                  and exists (
                    select
                    from
                      "tag_asset"
                      inner join "tag" on "tag"."id" = "tag_asset"."tagId"
                    where
                      "tag_asset"."assetId" = "live_photo_still"."id"
                      and "tag"."userId" = $10
                  )
              )
            )
          )
          or (
            exists (
              select
              from
                "tag_asset"
                inner join "tag_closure" on "tag_closure"."id_descendant" = "tag_asset"."tagId"
              where
                "tag_asset"."assetId" = "asset"."id"
                and "tag_closure"."id_ancestor" = any ($11::uuid[])
            )
            or (
              "asset"."visibility" = 'hidden'
              and exists (
                select
                from
                  "asset" as "live_photo_still"
                where
                  "live_photo_still"."livePhotoVideoId" = "asset"."id"
                  and exists (
                    select
                    from
                      "tag_asset"
                      inner join "tag_closure" on "tag_closure"."id_descendant" = "tag_asset"."tagId"
                    where
                      "tag_asset"."assetId" = "live_photo_still"."id"
                      and "tag_closure"."id_ancestor" = any ($12::uuid[])
                  )
              )
            )
          )
        )
        and (
          not exists (
            select
            from
              "tag_asset"
              inner join "tag_closure" on "tag_closure"."id_descendant" = "tag_asset"."tagId"
            where
              "tag_asset"."assetId" = "asset"."id"
              and "tag_closure"."id_ancestor" = any ($13::uuid[])
          )
          and (
            "asset"."visibility" != 'hidden'
            or not exists (
              select
              from
                "asset" as "live_photo_still"
              where
                "live_photo_still"."livePhotoVideoId" = "asset"."id"
                and exists (
                  select
                  from
                    "tag_asset"
                    inner join "tag_closure" on "tag_closure"."id_descendant" = "tag_asset"."tagId"
                  where
                    "tag_asset"."assetId" = "live_photo_still"."id"
                    and "tag_closure"."id_ancestor" = any ($14::uuid[])
                )
            )
          )
        )
        and "asset"."isPrivate" = $15
      )
    )
  )
order by
  face_search.embedding <=> query.embedding
limit
