-- PersonSuggestionRepository.getDifferentPersonGroupIds
select
  "targetPersonGroupId"
from
  "person_suggestion"
where
  "faceId" = $1
  and "status" = $2

-- PersonSuggestionRepository.getFacesDifferentFrom
select
  "faceId"
from
  "person_suggestion"
where
  "faceId" = any ($1::uuid[])
  and "targetPersonGroupId" = $2
  and "status" = $3

-- PersonSuggestionRepository.getPeopleDifferentFrom
select
  "personGroupId",
  "targetPersonGroupId"
from
  "person_suggestion"
where
  "ownerId" = $1
  and "status" = $2
  and (
    (
      "personGroupId" = $3
      and "targetPersonGroupId" = any ($4::uuid[])
    )
    or (
      "targetPersonGroupId" = $5
      and "personGroupId" = any ($6::uuid[])
    )
  )

-- PersonSuggestionRepository.moveToPerson
begin
delete from "person_suggestion"
where
  "ownerId" = $1
  and (
    "status" in ($2, $3)
    or (
      "personGroupId" = $4
      and "targetPersonGroupId" = $5
    )
    or (
      "personGroupId" = $6
      and "targetPersonGroupId" = $7
    )
  )
  and (
    "personGroupId" = $8
    or "targetPersonGroupId" = $9
  )
delete from "person_suggestion" as "moved"
where
  "moved"."ownerId" = $1
  and exists (
    select
      "kept"."id"
    from
      "person_suggestion" as "kept"
    where
      "kept"."ownerId" = "moved"."ownerId"
      and (
        (
          "moved"."personGroupId" = $2
          and (
            (
              "kept"."personGroupId" = $3
              and "kept"."targetPersonGroupId" = "moved"."targetPersonGroupId"
            )
            or (
              "kept"."targetPersonGroupId" = $4
              and "kept"."personGroupId" = "moved"."targetPersonGroupId"
            )
          )
        )
        or (
          "moved"."targetPersonGroupId" = $5
          and (
            (
              "kept"."targetPersonGroupId" = $6
              and (
                "kept"."personGroupId" = "moved"."personGroupId"
                or "kept"."faceId" = "moved"."faceId"
              )
            )
            or (
              "kept"."personGroupId" = $7
              and "kept"."targetPersonGroupId" = "moved"."personGroupId"
            )
          )
        )
      )
  )
update "person_suggestion"
set
  "personGroupId" = $1
where
  "ownerId" = $2
  and "personGroupId" = $3
update "person_suggestion"
set
  "targetPersonGroupId" = $1
where
  "ownerId" = $2
  and "targetPersonGroupId" = $3
commit

-- PersonSuggestionRepository.getFaceForCrop
select
  "asset_face"."id",
  "asset_face"."boundingBoxX1" as "x1",
  "asset_face"."boundingBoxY1" as "y1",
  "asset_face"."boundingBoxX2" as "x2",
  "asset_face"."boundingBoxY2" as "y2",
  "asset_face"."imageWidth" as "oldWidth",
  "asset_face"."imageHeight" as "oldHeight",
  "asset_face"."frameTimestamp",
  "asset_face"."isWholeAsset",
  "asset"."id" as "assetId",
  "asset"."ownerId",
  "asset"."type",
  "asset"."originalPath",
  "asset"."isPrivate",
  "asset_exif"."orientation" as "exifOrientation",
  (
    select
      "asset_file"."path"
    from
      "asset_file"
    where
      "asset_file"."assetId" = "asset"."id"
      and "asset_file"."type" = 'preview'
      and "asset_file"."isEdited" = false
  ) as "previewPath",
  (
    select
      to_json(obj)
    from
      (
        select
          "asset_video"."index",
          "asset_video"."codecName",
          "asset_video"."profile",
          "asset_video"."level",
          "asset_video"."bitrate",
          "asset_exif"."exifImageWidth" as "width",
          "asset_exif"."exifImageHeight" as "height",
          "asset_video"."pixelFormat",
          "asset_video"."frameCount",
          "asset_exif"."fps" as "frameRate",
          "asset_video"."timeBase",
          case
            when "asset_exif"."orientation" = '6' then -90
            when "asset_exif"."orientation" = '8' then 90
            when "asset_exif"."orientation" = '3' then 180
            else 0
          end as "rotation",
          "asset_video"."colorPrimaries",
          "asset_video"."colorMatrix",
          "asset_video"."colorTransfer",
          "asset_video"."dvProfile",
          "asset_video"."dvLevel",
          "asset_video"."dvBlSignalCompatibilityId"
        from
          (
            select
              1
          ) as "dummy"
        where
          "asset_video"."assetId" is not null
      ) as obj
  ) as "videoStream"
from
  "asset_face"
  inner join "asset" on "asset"."id" = "asset_face"."assetId"
  left join "asset_exif" on "asset_exif"."assetId" = "asset"."id"
  left join "asset_video" on "asset_video"."assetId" = "asset"."id"
where
  "asset_face"."id" = $1
  and "asset_face"."deletedAt" is null
  and "asset"."deletedAt" is null

